import pathlib,json,hashlib,datetime,re
p=pathlib.Path(__file__).parent
def load(n):return json.loads((p/n).read_text(encoding='utf-8'))
def save(n,o):(p/n).write_text(json.dumps(o,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
