 if 'scripts' in obj:obj['scripts']=[v for v in obj['scripts'] if not re.search(r'analytics|translate|email-decode',v,re.I)]
 if 'publicResultInterfaceSnippets' in obj:obj['publicResultInterfaceSnippets']=[v for v in obj['publicResultInterfaceSnippets'] if re.search(r'GetElection|GetContest|GetClient|totalResultsBaseUrl|appConfig|ServiceRoot|hidElectionDate|SearchResults|blob=|getData|Data\?|Races|Vote|Configuration|ElectionDates|RefreshTimer',v,re.I)]
